//! Rust library with public APIs that use a C++ type (exposed to Rust by
//! `rust_api_from_cpp`).  C++ bindings for this library (generated by
//! `cpp_api_from_rust`) should refer to the original C++ type.

chromium::import! {
    "//build/rust/tests/test_rust_api_from_cpp:self_contained_target_rs_api"
        as self_contained_target;
}

use self_contained_target::CcPodStruct;

pub fn double_cc_pod_struct(s: CcPodStruct) -> CcPodStruct {
    CcPodStruct { value: s.value * 2 }
}
